fun process(x: Int, a: Int, b: Int, c: Int, count: IntArray) {
    if (a != x || b != x || c != x) {
        var newC = c
        if (c != x) {
            newC = if (a + b > x) x else a + b - 1
            count[0]++
        }
        process(x, newC, a, b, count)
    }
}

fun main() {
    val (x, y) = readLine()!!.split(' ').map { it.toInt() }
    val count = IntArray(1)
    process(x, y, y, y, count)
    println(count[0])
}

