tailrec fun calculate(x: Int, a: Int, b: Int, c: Int, count: Int): Int {
    if (a != x || b != x || c != x) {
        var newC = c
        var newCount = count
        if (c != x) {
            if (a + b > x) {
                newC = x
            } else {
                newC = a + b - 1
            }
            newCount++
        }
        return calculate(x, newC, a, b, newCount)
    }
    return count
}

fun main() {
    val scanner = Scanner(System.`in`)
    val x = scanner.nextInt()
    val y = scanner.nextInt()
    val result = calculate(x, y, y, y, 0)
    println(result)
}

